  ('ng-amp8-crocodile-tank', 'Spotlight', 8, 'Small target: Called Shot, -4 to strike.', 5),
  ('ng-amp8-crocodile-tank', 'Box Missile Launcher (1, rear)', 80, NULL, 6),
