  ('ng-su7-crayfish-sub', 'Mini-Torpedo Launchers (2, one each side of the nose)', 30, 'Each. Small target: Called Shot, -4 to strike.', 2),
  ('ng-su7-crayfish-sub', 'Large Forward Lights (1 per front of each tread housing)', 10, 'Each. Small target: Called Shot, -4 to strike.', 3),
  ('ng-su7-crayfish-sub', 'Small Forward Lights (3 per front of each tread housing)', 5, 'Each. Small target: Called Shot, -4 to strike.', 4),
