  ('ng-su7-crayfish-sub', 'Forward Windows (2, large)', 35, 'Each. Small target: Called Shot, -4 to strike. A metal plate slides over each in combat or once the glass is badly weakened; losing glass and plate both lets the water in.', 6),
  ('ng-su7-crayfish-sub', 'Plate Armor for Windows (2)', 70, 'Each. Small target: Called Shot, -4 to strike.', 7),
  ('ng-su7-crayfish-sub', 'Hatch (3, two on top, one in underbelly)', 75, 'Each. Small target: Called Shot, -4 to strike.', 8),
  ('ng-su7-crayfish-sub', 'Robot Arms (one on each side)', 100, 'Each. Small target: Called Shot, -4 to strike.', 9),
  ('ng-su7-crayfish-sub', 'Tread Housings (2 on each side of sub)', 120, 'Each. One set lost: crawling speed -80%, -20% piloting, and a plain trail behind it; both lost, it cannot move on land or the bottom.', 10),
  ('ng-su7-crayfish-sub', 'Propeller Housing', 120, 'Below the waterline, so it can be hit only from under the surface. Destroyed, the propeller is out and the sub drifts, surfaces, or crawls the bottom on its treads at 5 mph (8 km).', 11),
  ('ng-su7-crayfish-sub', 'Main Body', 280, 'Reduced to zero, the vehicle shuts down completely and is useless; in the water it sinks within 5D6 minutes.', 12),
