INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('ng-amp8-crocodile-tank', 1, 'NG-L8 Laser Cannon', 'Three settings: 3D6 M.D., 5D6 M.D. or 6D6+6 M.D.', 1, '4,000 ft (1,219 m)', 'Each shot is one melee attack', 'Effectively unlimited on nuclear or Solid Oxide; 40 full-power blasts per charge on electric battery', NULL, 'Standard, the main gun. Chosen over a rail gun for its unlimited payload. The barrel has a 45 degree up and down arc, and the whole turret turns 360 degrees to bring it on target.'),
  ('ng-amp8-crocodile-tank', 2, 'NG-I830 Ion Turret with Spotlight', '4D6 M.D. per blast', 1, '2,000 ft (610 m), the spotlight''s reach as well', 'Each blast is one melee attack', 'Effectively unlimited on nuclear or Solid Oxide; 60 full-power blasts per charge on electric battery', NULL, 'Standard. A small ion blaster paired with a spotlight on a mount of its own, apart from the main gun, worked by either crewman; turns 360 degrees with a 45 degree up and down arc.'),
  ('ng-amp8-crocodile-tank', 3, 'Short-Range Missile Box Launcher', 'By missile type; high explosive (2D6x10 M.D., 15 ft/4.6 m radius) and armor piercing (2D6x10 M.D., 5 ft/1.5 m radius) are standard', 1, 'Usually 5 miles (8 km); 3 miles (4.8 km) for fragmentation or plasma/napalm', 'One at a time or volleys of two', 'Four missiles', '+3 to strike, as guided missiles', 'Standard. A box launcher at the back that slides rearward or forward to sit behind the turret, clear of the main gun; turns 360 degrees with a 45 degree up and down arc. For tanks, giant robots, fortifications, ships and buildings.'),
  ('ng-amp8-crocodile-tank', 4, 'Grenade Dispensers (2)', 'Smoke only, never explosive grenades: a 50x50 ft (15x15 m) screen from 2 grenades, 100x100 ft (30.5 x 30.5 m) from 4; shooting into or out of it is -10 to strike man-sized targets and -6 against large vehicles', 0, 'About 100 ft (30.5 m) in front of the vehicle', 'Patterns of two or four grenades', '8 grenades; four per dispenser', NULL, 'Standard. Smoke screens to blunt long-range fire and cover a withdrawal, so troops and other vehicles can shift position under them. The location list calls them Smoke Dispensers. The entry repeats the Alligator''s wording, so its penalty names the APC.'),
  ('ng-su7-crayfish-sub', 1, 'Mini-Missile/Mini-Torpedo Launchers (2)', 'By missile or torpedo type; 2D4x10 M.D. high explosive or 1D6x10 M.D. plasma mini-torpedoes', 1, 'One mile (1.6 km)', 'One at a time or volleys of two', '16 mini-torpedoes or mini-missiles; eight per launcher', NULL, 'Standard. Two tubes in the nose between the tread housings; torpedoes are the usual load underwater.'),
  ('ng-su7-crayfish-sub', 2, 'Blue-Green Laser Turrets (2)', '4D6 M.D. per single blast (the entry prints "46 M.D."); the two cannot fire linked', 1, '2,000 ft (610 m)', 'Each blast is one melee attack for its gunner', 'Effectively unlimited on nuclear or Solid Oxide; 90 shots per charge on electric battery', NULL, 'Standard. Low-profile turrets on top and underneath, toward the nose, each turning 360 degrees with a 45 degree up and down arc; also used to cut through debris, salvage and the hulls of wrecks.'),
  ('ng-su7-crayfish-sub', 3, 'Robot Arms (2)', 'Restrained punch or swat 1D4 M.D.; full strength 2D6 M.D.; no power punch or kick (Robot P.S. 34)', 1, '12 ft (3.6 m) reach beyond the nose', NULL, NULL, NULL, 'Standard, for excavation and salvage first and fighting second; folded away when not in use. 100 M.D.C. each.'),
  ('ng-s3-harbormaster-missile-boat', 1, 'NG-SRM309 Short-Range Missile Launchers (3)', 'By missile type; high explosive (2D6x10 M.D., 15 ft/4.5 m radius) and armor piercing (2D6x10 M.D., 5 ft/1.5 m radius) are standard', 1, 'About 5 miles (8 km); 3 miles (4.8 km) for fragmentation or plasma/napalm', 'One at a time or volleys of two or three', '9 missiles; three per launcher', NULL, 'Standard, the main weapon. Outranges naval guns and brings down aircraft; the warhead is chosen for the target.'),
  ('ng-s3-harbormaster-missile-boat', 2, 'NG-LS09 Laser Cannon Deck Gun', '5D6 M.D. per blast', 1, '4,000 ft (1,219 m)', 'Each blast is one of the gunner''s melee attacks', 'Effectively unlimited on nuclear or Solid Oxide; 70 shots on electric or fuel power', NULL, 'Standard. Turns 180 degrees with a 90 degree up and down arc; aimed by remote from the bridge or by hand from a fold-down seat or the open deck, at boats, sea monsters, things just beneath the surface, and missiles, aircraft and power armor flying low.'),
  ('ng-s3-harbormaster-missile-boat', 3, 'NG-BGL03 Blue-Green Underwater Laser Turret', '4D6 M.D. per blast', 1, '2,000 ft (610 m)', 'Each blast is one melee attack', 'Effectively unlimited on nuclear or Solid Oxide; 90 shots on electric or fuel power', NULL, 'Standard. Rides a track below the waterline, aimed through a camera link from inside, usually by its own gunner; turns 360 degrees with a 90 degree downward arc against torpedoes, sea monsters, aquatic troops and submersibles.'),
  ('ng-s1-sandfish-landing-craft', 1, 'NG-202 Rail Gun', '1D4x10 M.D. per 40-round burst; 1D4 M.D. per single round', 1, '4,000 ft (1,219 m)', 'Each single shot or burst is one melee attack', 'A 6,000-round drum per gun, 150 bursts', NULL, 'Standard: two, on the bow (gear row ng-202-rail-gun). Kept mainly to drive off sea monsters and to cover the craft as it backs off the beach.'),
  ('ng-s1-sandfish-landing-craft', 2, 'Grenade Dispensers (2)', 'Smoke only, never explosive grenades: a 50x50 ft (15x15 m) screen from 2 grenades, 100x100 ft (30.5 x 30.5 m) from 4', 0, '100 ft (30.5 m) in front of the vehicle', 'Patterns of two or four grenades', '8 grenades; four per dispenser', NULL, 'Standard. The Crocodile tank''s smoke screen system, fitted because landing cargo on a hostile beach is much like an amphibious assault.');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 4 machines are in' AS assertion, count(*) AS got, 4 AS want
  FROM vehicles WHERE slug IN ('ng-amp8-crocodile-tank', 'ng-su7-crayfish-sub', 'ng-s3-harbormaster-missile-boat', 'ng-s1-sandfish-landing-craft');
SELECT 'their 35 locations are in' AS assertion, count(*) AS got, 35 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('ng-amp8-crocodile-tank', 'ng-su7-crayfish-sub', 'ng-s3-harbormaster-missile-boat', 'ng-s1-sandfish-landing-craft');
SELECT 'their 12 weapon entries are in' AS assertion, count(*) AS got, 12 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('ng-amp8-crocodile-tank', 'ng-su7-crayfish-sub', 'ng-s3-harbormaster-missile-boat', 'ng-s1-sandfish-landing-craft');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('ng-amp8-crocodile-tank', 'ng-su7-crayfish-sub', 'ng-s3-harbormaster-missile-boat', 'ng-s1-sandfish-landing-craft') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('~320-northern-gun-2-aquatic-b.sql');
